import com.mikael8367.nexustech.worldgen.NovaAnexoCandidate.*;
import java.util.Arrays;
/** Offline only. Compile with Java 8 together with NovaAnexoCandidate.java; run main. */
public class NovaAnexoCandidateAuditTest {
 static int checks; static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);} static void bad(Runnable r){checks++;try{r.run();throw new AssertionError("expected IllegalArgumentException");}catch(IllegalArgumentException e){}}
 static int idx(int x,int y,int z){return (y*16+z)*16+x;}
 static byte[] flat(int h,int y){byte[] b=new byte[h*256];for(int i=0;i<h;i++)Arrays.fill(b,i*256,(i+1)*256,i<y?NovaAnexoCandidate.SOLID:NovaAnexoCandidate.AIR);return b;}
 static Candidate sel(long seed,int cx,int cz,byte[] b,boolean[] r,Config c){return NovaAnexoCandidate.select(seed,new Snapshot(cx,cz,b.length/256,b,r,true),c);}
 static boolean eq(Candidate a,Candidate b){return a==null?b==null:b!=null&&a.x==b.x&&a.y==b.y&&a.z==b.z&&a.chunkX==b.chunkX&&a.chunkZ==b.chunkZ&&a.margin==b.margin;}
 public static void main(String[] args){
 Config c=new Config(1,3,20,20,1);byte[] b=flat(40,20);boolean[] r=new boolean[256];Candidate a=sel(123,-2,-3,b,r,c);ok(a!=null&&a.y==20&&a.chunkX==-2&&a.chunkZ==-3,"negative/y");int x=a.x+32,z=a.z+48;
 for(int i=0;i<100;i++)ok(eq(a,sel(123,-2,-3,b,r,c)),"determinism");Snapshot frozen=new Snapshot(-2,-3,40,b,r,true);Arrays.fill(b,NovaAnexoCandidate.UNKNOWN);Arrays.fill(r,true);ok(eq(a,NovaAnexoCandidate.select(123,frozen,c)),"snapshot cloning");ok(NovaAnexoCandidate.select(123,new Snapshot(0,0,40,flat(40,20),new boolean[256],false),c)==null,"incomplete reservation");
 for(int m=0;m<=2;m++){Config cm=new Config(m,3,20,20,1);boolean[] sx=new boolean[16],sz=new boolean[16];byte[] terrain=flat(40,20);for(int s=0;s<500;s++){Candidate q=sel(s,0,0,terrain,new boolean[256],cm);ok(q!=null&&q.x>=m&&q.x+10+m<16&&q.z>=m&&q.z+10+m<16,"margin boundary");sx[q.x]=sz[q.z]=true;}for(int i=m;i<=5-m;i++)ok(sx[i]&&sz[i],"all origins");}
 for(int dz=z-1;dz<=z+11;dz++)for(int dx=x-1;dx<=x+11;dx++){boolean[] reserved=new boolean[256];reserved[dz*16+dx]=true;ok(sel(123,-2,-3,flat(40,20),reserved,c)==null,"reservation");byte[] t=flat(40,20);t[idx(dx,39,dz)]=NovaAnexoCandidate.BLOCKED;ok(sel(123,-2,-3,t,new boolean[256],c)==null,"blocked/water above");t=flat(40,20);t[idx(dx,20,dz)]=NovaAnexoCandidate.UNKNOWN;ok(sel(123,-2,-3,t,new boolean[256],c)==null,"unknown");if(dx>=x&&dx<x+11&&dz>=z&&dz<z+11)for(int yy=17;yy<20;yy++){t=flat(40,20);t[idx(dx,yy,dz)]=NovaAnexoCandidate.AIR;ok(sel(123,-2,-3,t,new boolean[256],c)==null,"cave");t[idx(dx,yy,dz)]=NovaAnexoCandidate.BLOCKED;ok(sel(123,-2,-3,t,new boolean[256],c)==null,"unsafe support");}}
 b=flat(40,20);b[idx(x,16,z)]=NovaAnexoCandidate.AIR;ok(sel(123,-2,-3,b,new boolean[256],c)!=null,"deeper cave not sampled");Candidate q=sel(123,-2,-3,flat(40,21),new boolean[256],new Config(1,3,18,22,1));ok(q!=null&&q.y==21,"surface height");ok(sel(1,0,0,flat(14,1),new boolean[256],new Config(0,1,1,1,1))==null,"short snapshot");
 for(int cx:new int[]{-134217728,134217727}){q=sel(4,cx,0,flat(40,20),new boolean[256],c);ok(q!=null&&(long)q.x>=16L*cx&&(long)q.x+11<=16L*cx+15,"integer limit");}for(int cx:new int[]{-134217729,134217728,Integer.MIN_VALUE,Integer.MAX_VALUE}){ok(sel(4,cx,0,flat(40,20),new boolean[256],c)==null,"x overflow");ok(sel(4,0,cx,flat(40,20),new boolean[256],c)==null,"z overflow");}
 bad(()->new Config(-1,3,4,10,1));bad(()->new Config(3,3,4,10,1));bad(()->new Config(1,0,4,10,1));bad(()->new Config(1,257,257,257,1));bad(()->new Config(1,3,2,10,1));bad(()->new Config(1,3,4,3,1));bad(()->new Config(1,3,4,243,1));bad(()->new Config(1,3,4,10,0));bad(()->new Snapshot(0,0,0,new byte[0],new boolean[256],true));bad(()->new Snapshot(0,0,257,new byte[65792],new boolean[256],true));bad(()->new Snapshot(0,0,1,null,new boolean[256],true));bad(()->new Snapshot(0,0,1,new byte[255],new boolean[256],true));bad(()->new Snapshot(0,0,1,new byte[256],null,true));bad(()->new Snapshot(0,0,1,new byte[256],new boolean[255],true));bad(()->{byte[] t=new byte[256];t[0]=-1;new Snapshot(0,0,1,t,new boolean[256],true);});bad(()->{byte[] t=new byte[256];t[255]=4;new Snapshot(0,0,1,t,new boolean[256],true);});bad(()->NovaAnexoCandidate.select(0,null,c));bad(()->NovaAnexoCandidate.select(0,frozen,null));
 int n=12000,count=0;byte[] t=flat(15,1);Config fc=new Config(0,1,1,1,4);for(int i=0;i<n;i++)if(sel(i,0,0,t,new boolean[256],fc)!=null)count++;ok(count>2700&&count<3300,"gate distribution");System.out.println("PASS checks="+checks+" gate="+count+"/"+n+" theoretical=1/4; flat synthetic snapshots, not placement rate");
 }
}